def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    seeds=[]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2:
                near=sum(0<=rr<h and 0<=cc<w and grid[rr][cc]==3 for rr,cc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)))
                if near>=2: seeds.append((r,c))
    for r,c in seeds:
        for rr in range(max(0,r-1),min(h,r+2)):
            for cc in range(max(0,c-1),min(w,c+2)):
                if grid[rr][cc]!=2: out[rr][cc]=1
    return out
